"""字段取值集合、匹配语义以及 :class:`Schedule` 类型。"""

from bisect import bisect_right
from dataclasses import dataclass


MINUTE = "minute"
HOUR = "hour"
DAY_OF_MONTH = "day_of_month"
MONTH = "month"
DAY_OF_WEEK = "day_of_week"

FIELD_NAMES = (MINUTE, HOUR, DAY_OF_MONTH, MONTH, DAY_OF_WEEK)

# 各字段允许的最小值与最大值。星期字段的 7 在解析阶段归一化为 0（周日）。
FIELD_RANGES = {
    MINUTE: (0, 59),
    HOUR: (0, 23),
    DAY_OF_MONTH: (1, 31),
    MONTH: (1, 12),
    DAY_OF_WEEK: (0, 7),
}

MONTH_NAMES = {
    "JAN": 1,
    "FEB": 2,
    "MAR": 3,
    "APR": 4,
    "MAY": 5,
    "JUN": 6,
    "JUL": 7,
    "AUG": 8,
    "SEP": 9,
    "OCT": 10,
    "NOV": 11,
    "DEC": 12,
}

WEEKDAY_NAMES = {
    "SUN": 0,
    "MON": 1,
    "TUE": 2,
    "WED": 3,
    "THU": 4,
    "FRI": 5,
    "SAT": 6,
}


class CronField:
    """单个字段解析后的取值集合。

    ``values`` 为升序去重后的整数元组；``is_star`` 表示原字段是否以 ``*``
    开头（``*``、``*/n`` 都算）。DOM/DOW 的 POSIX 并集规则依赖该标记：
    在 vixie cron 中，只要字段词法上是星号，就不参与“两者都限定”的分支。
    """

    __slots__ = ("values", "is_star")

    def __init__(self, values, is_star):
        self.values = tuple(values)
        self.is_star = is_star

    def contains(self, value):
        return value in self.values

    def next_value_at_or_above(self, value):
        """返回集合中 >= value 的最小值，不存在则返回 None。"""
        idx = bisect_right(self.values, value - 1)
        if idx < len(self.values):
            return self.values[idx]
        return None

    @property
    def minimum(self):
        return self.values[0]

    def __eq__(self, other):
        if not isinstance(other, CronField):
            return NotImplemented
        return self.values == other.values and self.is_star == other.is_star

    def __repr__(self):
        return "CronField(values=%r, is_star=%r)" % (self.values, self.is_star)


@dataclass(frozen=True)
class Schedule:
    """解析后的 Cron 计划。

    通过 :func:`cronspec.parser.parse` 创建；匹配与触发时间计算方法定义在
    :mod:`cronspec.engine` 中，并以方法形式挂到本类上。
    """

    raw: str
    minute: CronField
    hour: CronField
    day_of_month: CronField
    month: CronField
    day_of_week: CronField

    def day_matches(self, year, month, day, cron_weekday):
        """按 POSIX/vixie cron 语义判断某日是否参与触发。

        ``cron_weekday`` 为 0（周日）到 6（周六）。

        * DOM 与 DOW 都被显式限定（词法上都不是 ``*``）时取并集；
        * 只有一个被限定时按限定的那个判断；
        * 两个都是 ``*`` 时每天参与。
        """
        dom_restricted = not self.day_of_month.is_star
        dow_restricted = not self.day_of_week.is_star
        if dom_restricted and dow_restricted:
            return (
                self.day_of_month.contains(day)
                or self.day_of_week.contains(cron_weekday)
            )
        if dom_restricted:
            return self.day_of_month.contains(day)
        if dow_restricted:
            return self.day_of_week.contains(cron_weekday)
        return True

    def matches(self, dt):
        # 延迟导入，避免 fields -> engine 的循环导入。
        from .engine import matches

        return matches(self, dt)

    def next_after(self, dt):
        from .engine import next_after

        return next_after(self, dt)

    def next_n(self, dt, n):
        from .engine import next_n

        return next_n(self, dt, n)

"""Cron 表达式词法分析、字段解析与人类可读描述。"""

from .errors import ScheduleSyntaxError
from .fields import (
    CronField,
    DAY_OF_MONTH,
    DAY_OF_WEEK,
    FIELD_NAMES,
    FIELD_RANGES,
    HOUR,
    MINUTE,
    MONTH,
    MONTH_NAMES,
    Schedule,
    WEEKDAY_NAMES,
)


# 短写（@reboot 属于一次性任务而非周期计划，不在支持范围内）。
SHORTCUTS = {
    "@yearly": "0 0 1 1 *",
    "@annually": "0 0 1 1 *",
    "@monthly": "0 0 1 * *",
    "@weekly": "0 0 * * 0",
    "@daily": "0 0 * * *",
    "@midnight": "0 0 * * *",
    "@hourly": "0 * * * *",
}

FIELD_NAME_MAPS = {
    MINUTE: None,
    HOUR: None,
    DAY_OF_MONTH: None,
    MONTH: MONTH_NAMES,
    DAY_OF_WEEK: WEEKDAY_NAMES,
}


def _tokenize(expr):
    """按空格或制表符切词，返回 (片段文本, 在原文中的起始下标) 列表。"""
    tokens = []
    index = 0
    length = len(expr)
    while index < length:
        if expr[index] in " \t":
            index += 1
            continue
        start = index
        while index < length and expr[index] not in " \t":
            index += 1
        tokens.append((expr[start:index], start))
    return tokens


def _resolve_value(token, field_name, name_map, field_text, position):
    """把数字或名字（如 JAN、MON）解析为整数，并做范围校验。"""
    if token.isdigit():
        number = int(token)
    elif (
        name_map is not None
        and token.isalpha()
        and token.upper() == token
        and token == token.upper()
    ):
        if token not in name_map:
            raise ScheduleSyntaxError(
                field_name,
                field_text,
                position,
                "%s 字段存在未知名字 %r，支持 %s"
                % (field_name, token, "、".join(name_map.keys())),
            )
        number = name_map[token]
    else:
        raise ScheduleSyntaxError(
            field_name,
            field_text,
            position,
            "%s 字段包含非法字符 %r，只允许数字、范围 - 、步进 / 、逗号以及"
            "受支持的名字" % (field_name, token),
        )

    low, high = FIELD_RANGES[field_name]
    if number < low or number > high:
        raise ScheduleSyntaxError(
            field_name,
            field_text,
            position,
            "%s 字段的值 %d 超出允许范围 %d-%d"
            % (field_name, number, low, high),
        )
    if field_name == DAY_OF_WEEK and number == 7:
        # POSIX 约定 0 与 7 都表示周日，内部统一为 0。
        number = 0
    return number


def _parse_fragment(fragment, field_name, name_map, field_text, position):
    """解析单个逗号片段，如 ``*``、``1-5``、``30-40/5``。"""
    if fragment == "":
        raise ScheduleSyntaxError(
            field_name,
            field_text,
            position,
            "%s 字段存在空片段，逗号两侧必须都有内容" % field_name,
        )

    slash_parts = fragment.split("/")
    if len(slash_parts) > 2:
        raise ScheduleSyntaxError(
            field_name,
            field_text,
            position,
            "%s 字段的片段 %r 中步进符 / 只能出现一次"
            % (field_name, fragment),
        )

    base = slash_parts[0]
    if len(slash_parts) == 2:
        step_token = slash_parts[1]
        if not step_token.isdigit() or int(step_token) == 0:
            raise ScheduleSyntaxError(
                field_name,
                field_text,
                position + base.__len__() + 1,
                "%s 字段的步进值 %r 必须是正整数（不允许 0 或负数）"
                % (field_name, step_token),
            )
        step = int(step_token)
    else:
        step = None

    if base == "*":
        is_star = True
        start_value, end_value = FIELD_RANGES[field_name]
        if field_name == DAY_OF_WEEK:
            # 星期字段内部取值上界为 6（7 已归一化为 0）。
            end_value = 6
    else:
        is_star = False
        if base.startswith("*"):
            raise ScheduleSyntaxError(
                field_name,
                field_text,
                position,
                "%s 字段的片段 %r 非法，星号只能单独作为范围起点"
                % (field_name, fragment),
            )
        range_parts = base.split("-")
        if len(range_parts) > 2:
            raise ScheduleSyntaxError(
                field_name,
                field_text,
                position,
                "%s 字段的片段 %r 中范围符 - 只能出现一次"
                % (field_name, fragment),
            )
        start_value = _resolve_value(
            range_parts[0], field_name, name_map, field_text, position
        )
        if len(range_parts) == 2:
            end_position = position + base.index("-") + 1
            end_value = _resolve_value(
                range_parts[1],
                field_name,
                name_map,
                field_text,
                end_position,
            )
            if start_value > end_value:
                raise ScheduleSyntaxError(
                    field_name,
                    field_text,
                    position,
                    "%s 字段范围倒序：%d 大于 %d，范围必须从小到大"
                    % (field_name, start_value, end_value),
                )
        else:
            end_value = start_value
        if step is not None and len(range_parts) == 1:
            raise ScheduleSyntaxError(
                field_name,
                field_text,
                position,
                "%s 字段的片段 %r 非法，步进写法必须是 */n 或 范围/n 形式"
                % (field_name, fragment),
            )

    if step is None:
        step = 1
    return list(range(start_value, end_value + 1, step)), is_star


def _parse_field(field_text, field_name, field_start):
    """解析一整个字段（逗号组合），并保留每个片段在原文中的起始位置。"""
    name_map = FIELD_NAME_MAPS[field_name]
    values = set()
    is_star = False
    offset = 0
    for fragment in field_text.split(","):
        fragment_values, fragment_is_star = _parse_fragment(
            fragment,
            field_name,
            name_map,
            field_text,
            field_start + offset,
        )
        values.update(fragment_values)
        is_star = is_star or fragment_is_star
        offset += len(fragment) + 1
    return CronField(sorted(values), is_star)


def parse(expr):
    """解析标准 5 字段 Cron 表达式或合法短写，返回 :class:`Schedule`。"""
    if not isinstance(expr, str):
        raise ScheduleSyntaxError(
            None,
            "" if expr is None else str(expr),
            0,
            "表达式必须是字符串，实际收到 %s" % type(expr).__name__,
        )

    stripped = expr.strip()
    if stripped == "":
        raise ScheduleSyntaxError(None, stripped, 0, "表达式为空")

    tokens = _tokenize(expr)

    if stripped[0] == "@":
        token_text, token_start = tokens[0]
        if token_text != stripped or len(tokens) != 1:
            raise ScheduleSyntaxError(
                None,
                stripped,
                0,
                "短写表达式不能再附带其他字段",
            )
        if token_text not in SHORTCUTS:
            raise ScheduleSyntaxError(
                None,
                token_text,
                token_start,
                "未知短写 %r，支持 %s"
                % (token_text, "、".join(sorted(SHORTCUTS))),
            )
        expanded = SHORTCUTS[token_text]
        fields = _parse_fields(_tokenize(expanded))
        return Schedule(raw=expr, **fields)

    if len(tokens) != 5:
        raise ScheduleSyntaxError(
            None,
            stripped,
            0,
            "表达式必须由 5 个字段（分 时 日 月 周）或一个合法短写组成，"
            "实际切分出 %d 个字段" % len(tokens),
        )

    return Schedule(raw=expr, **_parse_fields(tokens))


def _parse_fields(tokens):
    return {
        field_name: _parse_field(token_text, field_name, token_start)
        for (token_text, token_start), field_name in zip(tokens, FIELD_NAMES)
    }


# ---------------------------------------------------------------------------
# 人类可读描述（确定性输出：相同表达式永远得到相同字符串）
# ---------------------------------------------------------------------------

_WEEKDAY_CN = ("周日", "周一", "周二", "周三", "周四", "周五", "周六")


def _is_consecutive(values):
    return list(values) == list(range(values[0], values[-1] + 1))


def _render_number_list(values, pad=False):
    texts = ["%02d" % value if pad else str(value) for value in values]
    if len(texts) > 2 and _is_consecutive(values):
        return "%s-%s" % (texts[0], texts[-1])
    return "、".join(texts)


def _date_phrase(schedule):
    """返回日期部分短语，可直接与时间短语用空格拼接。"""
    dom = schedule.day_of_month
    dow = schedule.day_of_week
    month_restricted = not schedule.month.is_star
    dom_restricted = not dom.is_star
    dow_restricted = not dow.is_star

    months = _render_number_list(schedule.month.values)
    doms = _render_number_list(dom.values)
    dows = "、".join(_WEEKDAY_CN[value] for value in dow.values)

    if dom_restricted and dow_restricted:
        core = "%s 日或%s" % (doms, dows)
        if month_restricted:
            return "每年 %s 月的 %s" % (months, core)
        return "每月 %s" % core
    if dom_restricted:
        if month_restricted:
            return "每年 %s 月 %s 日" % (months, doms)
        return "每月 %s 日" % doms
    if dow_restricted:
        if month_restricted:
            return "每年 %s 月的%s" % (months, dows)
        return "每%s" % dows
    if month_restricted:
        return "每年 %s 月的每天" % months
    return "每天"


def _time_phrase(schedule, date_phrase):
    """返回 (最终描述, )；负责把分钟/小时组合进日期短语。"""
    minutes = schedule.minute.values
    hours = schedule.hour.values
    every_minute = schedule.minute.is_star and schedule.hour.is_star
    every_hour = schedule.hour.is_star and not every_minute

    if every_minute:
        return "每分钟" if date_phrase == "每天" else date_phrase + "每分钟"

    if every_hour:
        if minutes == (0,):
            clock = "每小时整点"
        else:
            clock = "每小时的 %s 分" % _render_number_list(minutes, pad=True)
        return clock if date_phrase == "每天" else "%s的%s" % (date_phrase, clock)

    if len(minutes) == 1 and len(hours) == 1:
        clock = "%02d:%02d" % (hours[0], minutes[0])
    elif len(minutes) == 1:
        clock = "%s 时 %02d 分" % (
            _render_number_list(hours, pad=True),
            minutes[0],
        )
    else:
        clock = "%s 时的 %s 分" % (
            _render_number_list(hours, pad=True),
            _render_number_list(minutes, pad=True),
        )
    return "%s %s" % (date_phrase, clock)


def describe_schedule(schedule):
    return _time_phrase(schedule, _date_phrase(schedule))


def describe(expr):
    """返回表达式的确定性中文描述。"""
    return describe_schedule(parse(expr))

"""触发时间搜索引擎。

搜索按字段推进：先跳到可能的月份，再在月内定位可能的日，再跳到时、分，
绝不逐分钟线性扫描。历法换算使用纯整数算术（Howard Hinnant 的 civil date
算法），内部 ``(年, 月, 日, 时, 分)`` 五元组不依赖 :class:`datetime.date`，
因此即使取触发时刻的数量超过 ``datetime`` 的 9999 年上限，内部搜索仍可进行。
"""

from datetime import datetime

from .errors import NoMatchingTimeError


# 搜索窗口上限（年）。公历星期每 400 年重复，闰年周期最长 8 年，
# 任何可行表达式都必然能在 400 年内命中，这里再留出余量。
SEARCH_LIMIT_YEARS = 400


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def days_in_month(year, month):
    if month == 2:
        return 29 if is_leap(year) else 28
    if month in (4, 6, 9, 11):
        return 30
    return 31


def _days_from_civil(year, month, day):
    """Howard Hinnant 公历日期 -> 自 1970-01-01 起的天数（支持任意整年）。"""
    y = year - (1 if month <= 2 else 0)
    era = y // 400
    yoe = y - era * 400
    doy = (153 * (month + (-3 if month > 2 else 9)) + 2) // 5 + day - 1
    doe = yoe * 365 + yoe // 4 - yoe // 100 + doy
    return era * 146097 + doe - 719468


def _civil_from_days(days):
    """``_days_from_civil`` 的逆运算。"""
    shifted = days + 719468
    era = (shifted - (146096 if shifted >= 0 else 0)) // 146097
    day_of_era = shifted - era * 146097
    year_of_era = (
        day_of_era - day_of_era // 1460 + day_of_era // 36524 - day_of_era // 146096
    ) // 365
    year = year_of_era + era * 400
    day_of_year = day_of_era - (
        365 * year_of_era + year_of_era // 4 - year_of_era // 100
    )
    month = (5 * day_of_year + 2) // 153
    day = day_of_year - (153 * month + 2) // 5 + 1
    month += 3 if month < 10 else -9
    if month <= 2:
        year += 1
    return year, month, day


def weekday_of(year, month, day):
    """返回 0（周日）到 6（周六）。"""
    return (_days_from_civil(year, month, day) + 4) % 7


def next_day(year, month, day):
    """返回次日的 (年, 月, 日)。"""
    if day < days_in_month(year, month):
        return year, month, day + 1
    if month < 12:
        return year, month + 1, 1
    return year + 1, 1, 1


def first_weekday_on_or_after(year, month, day, wanted, limit_day):
    """在同月 [day, limit_day] 内寻找下一个指定星期几，找不到返回 None。"""
    if day > limit_day:
        return None
    current = weekday_of(year, month, day)
    delta = (wanted - current) % 7
    candidate = day + delta
    return candidate if candidate <= limit_day else None


def _candidate_day(schedule, year, month, min_day):
    """在同月 >= min_day 的范围找下一个满足 DOM/DOW 规则的日，找不到返回 None。"""
    limit_day = days_in_month(year, month)
    if min_day > limit_day:
        return None

    dom_restricted = not schedule.day_of_month.is_star
    dow_restricted = not schedule.day_of_week.is_star
    candidates = []

    if dom_restricted:
        dom_day = schedule.day_of_month.next_value_at_or_above(min_day)
        if dom_day is not None and dom_day <= limit_day:
            candidates.append(dom_day)

    if dow_restricted:
        # 周一在周五之前时，必须逐个星期值试探；集合最多 7 个值，开销恒定。
        for wanted in schedule.day_of_week.values:
            dow_day = first_weekday_on_or_after(
                year, month, min_day, wanted, limit_day
            )
            if dow_day is not None:
                candidates.append(dow_day)

    if not dom_restricted and not dow_restricted:
        return min_day
    return min(candidates) if candidates else None


def _candidate_time(schedule, hour, minute, same_day):
    """在给定小时或其后寻找 (时, 分)；跨天返回 None。

    same_day 为 True 时只允许在 >= (hour, minute) 的当天时刻中寻找。
    """
    if same_day:
        next_hour = schedule.hour.next_value_at_or_above(hour)
        if next_hour is None:
            return None
        if next_hour == hour:
            next_minute = schedule.minute.next_value_at_or_above(minute)
            if next_minute is None:
                next_hour = schedule.hour.next_value_at_or_above(hour + 1)
                if next_hour is None:
                    return None
                return next_hour, schedule.minute.minimum
            return next_hour, next_minute
        return next_hour, schedule.minute.minimum
    return schedule.hour.minimum, schedule.minute.minimum


def next_tuple(schedule, year, month, day, hour, minute, strict_after=True):
    """核心搜索：返回严格晚于给定时刻的下一个 (年, 月, 日, 时, 分)。"""
    cursor_year, cursor_month = year, month
    first_month = True

    while cursor_year - year <= SEARCH_LIMIT_YEARS:
        month_value = (
            schedule.month.next_value_at_or_above(cursor_month)
            if first_month
            else schedule.month.minimum
        )
        if month_value is None or month_value < cursor_month:
            cursor_year += 1
            cursor_month = 1
            first_month = False
            continue
        cursor_month = month_value

        if (cursor_year, cursor_month) == (year, month):
            cursor_day = day
            same_day = True
        else:
            cursor_day = 1
            same_day = False

        while True:
            candidate_day = _candidate_day(
                schedule, cursor_year, cursor_month, cursor_day
            )
            if candidate_day is None:
                break

            day_same = same_day and candidate_day == day
            if day_same:
                time_result = _candidate_time(schedule, hour, minute, True)
            else:
                time_result = _candidate_time(schedule, 0, 0, False)

            if time_result is not None:
                candidate_hour, candidate_minute = time_result
                if (
                    not strict_after
                    or (candidate_hour, candidate_minute) > (hour, minute)
                    or candidate_day > day
                    or (cursor_year, cursor_month) != (year, month)
                ):
                    return (
                        cursor_year,
                        cursor_month,
                        candidate_day,
                        candidate_hour,
                        candidate_minute,
                    )

            # 当天没有可用时刻，推进到下一个候选日。
            if candidate_day == days_in_month(cursor_year, cursor_month):
                break
            cursor_day = candidate_day + 1
            same_day = False

        # 推进到下一月。
        if cursor_month == 12:
            cursor_year += 1
            cursor_month = 1
        else:
            cursor_month += 1
        first_month = False

    raise NoMatchingTimeError(
        "在 %d 年的搜索窗口内没有任何触发时刻，可能该日期组合不存在（"
        "如 2 月 30 日）" % SEARCH_LIMIT_YEARS
    )


def _check_feasible(schedule):
    """表达式级可行性预检：快速识别必然无解的日期组合。"""
    dom_restricted = not schedule.day_of_month.is_star
    dow_restricted = not schedule.day_of_week.is_star
